import sys

MOD = 998244353
powers = []


def ggt(a, b):
    if a < b:
        return ggt(b, a)
    if b == 0:
        return a
    return ggt(b, a % b)


def gcd(a, b):
    return a * b // ggt(a, b)


def gcd_range(n):
    result = 1
    for i in range(1, n + 1):
        result = gcd(result, i)
    return result


def init(n, k):
    global powers
    powers = [0] * k
    powers[0] = 1
    for i in range(1, k):
        powers[i] = n * powers[i - 1] % MOD


def solve(n, a, x, y, k, m):
    init(n, k)

    gcd_r = gcd_range(k - 1)
    r = [[0] * (k + 1) for _ in range(gcd_r)]

    for i in range(1, k + 1):
        for j in range(gcd_r):
            jump = j - j % (k + 1 - i)
            r[j][i] = (
                (n - 1) * r[j][i - 1]
                + r[jump][i - 1]
                + j * powers[i - 1]
            ) % MOD

    total = 0
    for _ in range(n):
        total += (
            r[a % gcd_r][k]
            + ((a // gcd_r) * gcd_r * k % MOD) * powers[k - 1] % MOD
        )
        total %= MOD
        a = (a * x + y) % m

    print(total)


data = list(map(int, sys.stdin.buffer.read().split()))
solve(*data[:6])

